questionvariables.text:
/* Define lists of non-square integers (irrational results) and square integers (rational results) */
irr_list: [2, 3, 5, 6, 7, 8, 10, 11, 12, 13, 14, 15];
rat_list: [1, 4, 9, 16, 25, 36];

/* Randomly choose whether this instance is rational (0) or irrational (1) */
type_choice: rand([0, 1]);

if type_choice = 1 then (
    n: rand(irr_list),
    correct_ans: "Irrational",
    explanation: sconcat("Since ", n, " is not a perfect square, its square root cannot be expressed as a ratio of two integers, making it irrational.")
) else (
    n: rand(rat_list),
    correct_ans: "Rational",
    explanation: sconcat("Since ", n, " is a perfect square, its square root simplifies to an integer, making it rational.")
);

/* The expression displayed to the student */
expr: sqrt(n);
